    ex de,hl
    and a
    sbc hl,de
    jr nc,LAB_ram_76ac
    add hl,de
    ex de,hl
    and a
    sbc hl,de
    xor 0x80
LAB_ram_76ac:
    rla
    rr h
    rr l
    ret
